import java.util.*;

class Solution {
    public List<List<String>> solveNQueens(int n) {
        List<List<String>> result = new ArrayList<>();
        int[] perm = new int[n];
        for (int i = 0; i < n; i++) perm[i] = i;
        permute(perm, 0, result, n);
        return result;
    }

    private void permute(int[] perm, int k, List<List<String>> result, int n) {
        if (k == n) {
            if (isValid(perm, n)) result.add(render(perm, n));
            return;
        }
        for (int i = k; i < n; i++) {
            swap(perm, k, i);
            permute(perm, k + 1, result, n);
            swap(perm, k, i);
        }
    }

    private boolean isValid(int[] perm, int n) {
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (Math.abs(i - j) == Math.abs(perm[i] - perm[j])) return false;
            }
        }
        return true;
    }

    private List<String> render(int[] perm, int n) {
        List<String> board = new ArrayList<>();
        for (int r = 0; r < n; r++) {
            StringBuilder sb = new StringBuilder();
            for (int c = 0; c < n; c++) {
                sb.append(c == perm[r] ? 'Q' : '.');
            }
            board.add(sb.toString());
        }
        return board;
    }

    private void swap(int[] a, int i, int j) {
        int t = a[i];
        a[i] = a[j];
        a[j] = t;
    }
}

import java.util.*;

class Solution {
    private int n;
    private char[][] board;
    private List<List<String>> result;
    private Set<Integer> cols;
    private Set<Integer> diag1;
    private Set<Integer> diag2;

    public List<List<String>> solveNQueens(int n) {
        this.n = n;
        this.board = new char[n][n];
        for (char[] row : board) Arrays.fill(row, '.');
        this.result = new ArrayList<>();
        this.cols = new HashSet<>();
        this.diag1 = new HashSet<>();
        this.diag2 = new HashSet<>();
        dfs(0);
        return result;
    }

    private void dfs(int row) {
        if (row == n) {
            List<String> snapshot = new ArrayList<>();
            for (char[] r : board) snapshot.add(new String(r));
            result.add(snapshot);
            return;
        }
        for (int col = 0; col < n; col++) {
            if (cols.contains(col) || diag1.contains(row - col) || diag2.contains(row + col)) {
                continue;
            }
            cols.add(col);
            diag1.add(row - col);
            diag2.add(row + col);
            board[row][col] = 'Q';

            dfs(row + 1);

            board[row][col] = '.';
            cols.remove(col);
            diag1.remove(row - col);
            diag2.remove(row + col);
        }
    }
}

import java.util.*;

class Solution {
    private int n;
    private char[][] board;
    private List<List<String>> result;

    public List<List<String>> solveNQueens(int n) {
        this.n = n;
        this.board = new char[n][n];
        for (char[] row : board) Arrays.fill(row, '.');
        this.result = new ArrayList<>();
        dfs(0, 0, 0, 0);
        return result;
    }

    private void dfs(int row, int cols, int diag1, int diag2) {
        if (row == n) {
            List<String> snapshot = new ArrayList<>();
            for (char[] r : board) snapshot.add(new String(r));
            result.add(snapshot);
            return;
        }
        for (int col = 0; col < n; col++) {
            int bit = 1 << col;
            if ((cols & bit) != 0 || (diag1 & bit) != 0 || (diag2 & bit) != 0) continue;

            board[row][col] = 'Q';
            dfs(row + 1, cols | bit, (diag1 | bit) << 1, (diag2 | bit) >> 1);
            board[row][col] = '.';
        }
    }
}
